// Both triggers land here. The form sends its fields directly; the webhook
// sends them as a JSON body.
const item = $input.first().json;
const fromWebhook = item.body !== undefined && item.headers !== undefined;
const data = fromWebhook ? item.body : item;

const topic = String(data.topic ?? '').trim();
const level = String(data.level ?? '').trim().toUpperCase();
if (!topic) throw new Error('topic is required');
if (!level) throw new Error('level is required, for example N4');

return [
  {
    json: {
      source: fromWebhook ? 'webhook' : 'form',
      topic,
      level,
      target_length: Number(data.target_length) || 400,
      article_type: String(data.article_type || 'Blog post').trim(),
    },
  },
];

// Turns the model's reply into the state that goes around the check loop.
const input = $('Draft prompt').first().json;
const reply = String($input.first().json.text ?? '');

const draft = parseJson(reply);
const title = String(draft.title ?? '').replace(/\s+/g, ' ').trim();
const body = String(draft.body ?? '').replace(/\r\n?/g, '\n').trim();
if (!title || !body) {
  throw new Error(`The draft has no title or body. Model reply: ${reply.slice(0, 300)}`);
}

const { prompt, model, ...settings } = input;
return [
  {
    json: {
      ...settings,
      list_name: `${settings.list}-${settings.level.toLowerCase()}`,
      // The title is checked and repaired too, as the first line.
      text: `${title}\n\n${body}`,
      round: 0,
      first_draft_pass_rate: null,
      first_draft_content_tokens: null,
      caught_words: [],
      caught_kanji: [],
      rejected_words: [],
      repairs: [],
      repair_errors: 0,
      tokens: {
        draft: { input: estimateTokens(prompt), output: estimateTokens(reply) },
        repair: { input: 0, output: 0 },
      },
    },
  },
];

// Models sometimes wrap the JSON in a code fence or add a sentence around it.
function parseJson(reply) {
  const start = reply.indexOf('{');
  const end = reply.lastIndexOf('}');
  if (start === -1 || end < start) {
    throw new Error(`No JSON object in the model reply: ${reply.slice(0, 300)}`);
  }
  return JSON.parse(reply.slice(start, end + 1));
}

// n8n doesn't pass the model's real token counts to later nodes, so this
// estimates them: about one token per Japanese character and four characters
// per token for everything else. Hidden reasoning tokens aren't counted.
function estimateTokens(text) {
  let cjk = 0;
  let other = 0;
  for (const ch of String(text)) {
    if (ch.codePointAt(0) >= 0x3000) cjk += 1;
    else other += 1;
  }
  return Math.ceil(cjk + other / 4);
}

// Adds the checker's result to the state and decides whether to stop.
const state = $('Round start').first().json;
const check = $input.first().json;

const caughtWords = new Set(state.caught_words);
const caughtKanji = new Set(state.caught_kanji);
// Words that aren't in the list at all, so a repair can't swap one for another.
const rejected = new Set(state.rejected_words);
for (const sentence of check.sentences) {
  for (const v of sentence.violations) {
    caughtWords.add(v.lemma);
    for (const k of v.kanji ?? []) caughtKanji.add(k);
    if (v.reason === 'not_in_list') rejected.add(v.lemma);
  }
}

const done = check.pass || state.round >= state.max_rounds;

// What the repair step gets: each failing sentence, what is wrong with it,
// and its neighbours for context.
const failing = [];
if (!done) {
  check.sentences.forEach((s, i) => {
    if (s.ok) return;
    failing.push({
      index: s.index,
      sentence: s.text,
      before: check.sentences[i - 1]?.text ?? '',
      after: check.sentences[i + 1]?.text ?? '',
      problems: s.violations.map(describe),
    });
  });
}

const first = state.round === 0;
return [
  {
    json: {
      ...state,
      check,
      done,
      failing,
      first_draft_pass_rate: first ? check.pass_rate : state.first_draft_pass_rate,
      first_draft_content_tokens: first ? check.content_tokens : state.first_draft_content_tokens,
      caught_words: [...caughtWords],
      caught_kanji: [...caughtKanji],
      rejected_words: [...rejected],
    },
  },
];

function describe(v) {
  if (v.reason === 'kanji_above_level') {
    const kana = v.suggestion?.replace(/^write in kana: /, '') ?? v.reading;
    return `「${v.surface}」 has kanji above ${state.level} (${v.kanji.join('')}). Write it in kana: ${kana}`;
  }
  return `「${v.surface}」 is not in the ${state.level} word list. Use a simpler word.`;
}

// Puts the rewritten sentences back in place and starts the next round.
const state = $('Repair prompt').first().json;
const reply = String($input.first().json.text ?? '');

let rewrites = {};
let repairErrors = state.repair_errors;
try {
  rewrites = parseJson(reply);
} catch (error) {
  // A bad reply uses up a round but doesn't stop the run: the next check
  // sends the same sentences again.
  repairErrors += 1;
}

const failing = new Map(state.failing.map((f) => [f.index, f]));
// The checker's offsets count code points, so work on an array of them.
const chars = Array.from(state.text);
const repairs = [];
// Go from the last sentence to the first so earlier offsets stay valid.
for (const s of [...state.check.sentences].reverse()) {
  const f = failing.get(s.index);
  const rewrite = rewrites[String(s.index)];
  if (!f || typeof rewrite !== 'string') continue;
  const sentence = rewrite.replace(/\s*\n\s*/g, '').trim();
  if (!sentence) continue;
  chars.splice(s.start, s.end - s.start, ...sentence);
  repairs.unshift({
    round: state.round + 1,
    index: s.index,
    original: s.text,
    problems: f.problems,
    repaired: sentence,
  });
}

const { prompt, model, check, failing: _failing, done, ...rest } = state;
return [
  {
    json: {
      ...rest,
      text: chars.join(''),
      round: state.round + 1,
      repairs: [...state.repairs, ...repairs],
      repair_errors: repairErrors,
      tokens: {
        ...state.tokens,
        repair: {
          input: state.tokens.repair.input + estimateTokens(prompt),
          output: state.tokens.repair.output + estimateTokens(reply),
        },
      },
    },
  },
];

// Models sometimes wrap the JSON in a code fence or add a sentence around it.
function parseJson(reply) {
  const start = reply.indexOf('{');
  const end = reply.lastIndexOf('}');
  if (start === -1 || end < start) {
    throw new Error(`No JSON object in the model reply: ${reply.slice(0, 300)}`);
  }
  return JSON.parse(reply.slice(start, end + 1));
}

// n8n doesn't pass the model's real token counts to later nodes, so this
// estimates them: about one token per Japanese character and four characters
// per token for everything else. Hidden reasoning tokens aren't counted.
function estimateTokens(text) {
  let cjk = 0;
  let other = 0;
  for (const ch of String(text)) {
    if (ch.codePointAt(0) >= 0x3000) cjk += 1;
    else other += 1;
  }
  return Math.ceil(cjk + other / 4);
}

// Splits the checked text back into title and body and writes the report.
const state = $input.first().json;
const [title, ...rest] = state.text.split('\n');
const body = rest.join('\n').trim();

const html = body
  .split(/\n\s*\n/)
  .map((p) => `<p>${escapeHtml(p.trim()).replace(/\n/g, '<br>')}</p>`)
  .join('\n');

const { tokens } = state;
const cost =
  (tokens.draft.input * state.draft_price_input +
    tokens.draft.output * state.draft_price_output +
    tokens.repair.input * state.repair_price_input +
    tokens.repair.output * state.repair_price_output) /
  1e6;

const report = {
  title,
  topic: state.topic,
  level: state.level,
  list: state.list_name,
  article_type: state.article_type,
  target_length: state.target_length,
  length: Array.from(body).length,
  pass: state.check.pass,
  final_pass_rate: state.check.pass_rate,
  first_draft_pass_rate: state.first_draft_pass_rate,
  content_tokens: state.check.content_tokens,
  first_draft_content_tokens: state.first_draft_content_tokens,
  rounds_used: state.round,
  violations_left: state.check.sentences.flatMap((s) =>
    s.violations.map((v) => ({ sentence: s.index, text: s.text, ...v })),
  ),
  unique_words_caught: state.caught_words,
  kanji_caught: state.caught_kanji,
  repairs: state.repairs,
  repair_errors: state.repair_errors,
  models: { draft: state.draft_model, repair: state.repair_model },
  tokens_estimated: {
    ...tokens,
    total: tokens.draft.input + tokens.draft.output + tokens.repair.input + tokens.repair.output,
  },
  estimated_cost_usd: Number(cost.toFixed(6)),
  execution_id: $execution.id,
};

return [{ json: { title, html, report, source: state.source } }];

function escapeHtml(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Adds the WordPress draft to the report and builds the page the form shows.
const { report, source } = $('Build post').first().json;
const post = $input.first().json;

const site = String(post.link ?? '').split('?')[0].replace(/\/$/, '');
report.post = {
  id: post.id,
  status: post.status,
  edit_url: `${site}/wp-admin/post.php?post=${post.id}&action=edit`,
};

const percent = (rate) => (rate === null ? 'n/a' : `${(rate * 100).toFixed(1)}%`);
const left = report.violations_left.length;
const items = [
  report.pass ? 'Every word and kanji is in the list.' : `${left} problem(s) left after ${report.rounds_used} rounds.`,
  `Pass rate: ${percent(report.first_draft_pass_rate)} in the first draft, ${percent(report.final_pass_rate)} at the end.`,
  `Repair rounds: ${report.rounds_used}.`,
  `Words caught: ${report.unique_words_caught.join('、') || 'none'}.`,
  `Estimated cost: $${report.estimated_cost_usd.toFixed(4)}.`,
];
const formHtml = [
  `<h3>${escapeHtml(report.title)}</h3>`,
  '<p>Saved as a WordPress draft (not published).</p>',
  `<ul>${items.map((i) => `<li>${escapeHtml(i)}</li>`).join('')}</ul>`,
  `<p><a href="${escapeHtml(report.post.edit_url)}" target="_blank">Open the draft</a></p>`,
].join('\n');

return [{ json: { report, source, form_html: formHtml } }];

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
